//! What the native diagram path knows without looking, generated by `tests/cd/native/gen_table.py`.

/// Hashes of macros, name and body, that may stay in a cell whatever they mention: `Tex::native_macro_hash`.  Sorted.
static SAFE: &[u64] = &[];

pub fn is_safe(h: u64) -> bool {
    SAFE.binary_search(&h).is_ok()
}
